import numpy as np
import time

_N = 17
_MIN_D = 6
_SEED = 32
_START = time.time()
_DEADLINE = 50.0  # Safety margin (90s limit, leave 40s buffer)

def _qr_code_generator():
    """
    Returns the generator matrix for the [17,8,5] binary quadratic residue code.
    """
    p = 17
    # Quadratic residues mod 17
    QR = set((i * i) % p for i in range(1, p))
    # The generator matrix is circulant, generated by the idempotent.
    # However, a simpler way for small p is to use the known structure or just build it via the parity check?
    # Let's use the standard construction:
    # The code is generated by the vector v where v_i = 1 if i is a QR, 0 otherwise?
    # No, that's the basis for the cyclic code.
    # We need a systematic or just any generator.
    # Let's use the fact that the [17,8,5] code is the code with generator polynomial g(x) = 1 + x^4 + x^6 + x^10 + x^11 + x^12 + x^13 + x^14 + x^16? 
    # Actually, for p=17, the QR code is generated by the idempotent in GF(2)[x]/(x^17-1).
    # Idempotent e(x) = (1/17) * sum_{i in QR} x^i? No, in GF(2).
    # Let's just use the known generator matrix rows (shifts of the idempotent).
    
    # Idempotent for p=17:
    # The QRs are {1, 2, 4, 8, 9, 13, 15, 16}.
    # The idempotent vector v has 1s at these positions.
    # The code is the cyclic code generated by v.
    # So the generator matrix consists of the 8 cyclic shifts of v.
    
    v = np.zeros(p, dtype=np.uint8)
    for q in QR:
        v[q] = 1
        
    G = np.zeros((8, p), dtype=np.uint8)
    for k in range(8):
        G[k] = np.roll(v, k)
        
    return G

def _construct_extended_qr():
    """
    Constructs the [18,9,6] extended QR code.
    """
    G17 = _qr_code_generator()
    
    # Step 1: Create [18,8,6] code by adding parity bit
    # Parity bit for row k is sum(G17[k]) % 2
    parities = G17.sum(axis=1) % 2
    G18_8 = np.column_stack((G17, parities))
    
    # Step 2: Add all-ones vector to get [18,9,6]
    ones = np.ones(18, dtype=np.uint8)
    G18_9 = np.vstack((G18_8, ones))
    
    # Generate all 512 codewords
    code = np.zeros((512, 18), dtype=np.uint8)
    for m in range(512):
        bits = np.array([(m >> j) & 1 for j in range(9)], dtype=np.uint8)
        code[m] = (bits @ G18_9) % 2
        
    return code

def _shorten_code(code, coord_to_fix=17):
    """
    Shortens the code by fixing 'coord_to_fix' to 0.
    """
    # Keep words where the bit at coord_to_fix is 0
    mask = code[:, coord_to_fix] == 0
    short_code = code[mask, :17]
    return short_code

def _popcount_vec(diffs):
    """Vectorized popcount."""
    d = diffs.astype(np.int64)
    cnt = np.zeros(len(d), dtype=np.int32)
    for s in range(_N):
        cnt += (d >> s) & 1
    return cnt

def _hamming_dist_int(a, b):
    """Hamming distance between two integers."""
    return bin(a ^ b).count('1')

def _is_valid_candidate(cand, code_list, min_d):
    """Check if cand has distance >= min_d from all words in code_list."""
    for w in code_list:
        if _hamming_dist_int(cand, w) < min_d:
            return False
    return True

def _greedy_add(code_list, min_d, deadline, rng):
    """
    Greedily add candidates to code_list.
    Candidates are generated by flipping 3 bits of existing words.
    Returns the extended code_list.
    """
    current_code = list(code_list)
    current_set = set(current_code)
    
    while time.time() < deadline - 2.0:
        # Generate a candidate by flipping 3 bits of a random existing word
        if len(current_code) == 0:
            cand = int(rng.integers(0, 1 << _N))
        else:
            idx = int(rng.integers(0, len(current_code)))
            base = current_code[idx]
            positions = list(range(_N))
            rng.shuffle(positions)
            flip_mask = 0
            for p in positions[:3]:
                flip_mask |= (1 << p)
            cand = base ^ flip_mask
        
        if cand in current_set:
            continue
        
        # Check validity
        valid = _is_valid_candidate(cand, current_code, min_d)
        
        if valid:
            current_code.append(cand)
            current_set.add(cand)
    
    return current_code

def _swap_local_search(code_list, min_d, deadline, rng):
    """
    1-for-1 swap local search: try to replace one word with a better one.
    A swap is beneficial if we can remove a word and add two new words.
    This is a heuristic to escape local optima.
    """
    current_code = list(code_list)
    current_set = set(current_code)
    n = len(current_code)
    
    # Precompute pairwise distances for speed
    # dist[i][j] = hamming distance between code[i] and code[j]
    dist = np.zeros((n, n), dtype=np.int32)
    for i in range(n):
        for j in range(i + 1, n):
            d = _hamming_dist_int(current_code[i], current_code[j])
            dist[i][j] = d
            dist[j][i] = d
    
    # Try swaps: for each word i, try to find a candidate c such that:
    # - dist(c, current_code[j]) >= min_d for all j != i
    # - c not in current_set
    # If found, replace current_code[i] with c (this is a neutral swap, size stays same)
    # But we want to grow the code, so this alone won't help.
    
    # Better: try to add a word by removing one.
    # For each word i, temporarily remove it, then try to add a candidate.
    # If we can add a candidate, we're back to the same size (removed 1, added 1).
    # To grow, we need to add without removing, which is what greedy does.
    
    # Alternative: 2-for-1 swap: remove 2 words, add 3 words.
    # This is more complex. Let's stick with a simpler approach.
    
    # Actually, the key insight from the inspiration is that structured neighborhood
    # search with multiple diverse random orderings helps.
    
    # Let's try a different approach: restart greedy with different random seeds
    # and keep the best result.
    
    return current_code

def construct():
    t0 = time.time()
    deadline = t0 + _DEADLINE
    
    # 1. Get the linear [17,8,6] code (256 words)
    ext_code = _construct_extended_qr()
    lin_code = _shorten_code(ext_code)
    
    # Convert to list of ints
    powers = (1 << np.arange(_N, dtype=np.int64))[::-1]
    code_list = (lin_code @ powers).astype(np.int64).tolist()
    
    # Ensure uniqueness (should be unique)
    code_set = set(code_list)
    
    # 2. Try to add more words (nonlinear extension)
    # Use multiple restarts with different random seeds
    rng = np.random.default_rng(42)
    
    best_code = list(code_list)
    best_size = len(best_code)
    
    # Run greedy multiple times with different seeds
    for restart in range(5):
        if time.time() > deadline - 5.0:
            break
        
        # Use a different seed for each restart
        rng_restart = np.random.default_rng(42 + restart)
        
        # Start from the linear code
        current_code = list(code_list)
        
        # Greedy add
        extended_code = _greedy_add(current_code, _MIN_D, deadline, rng_restart)
        
        if len(extended_code) > best_size:
            best_code = extended_code
            best_size = len(best_code)
    
    return best_code

def main():
    return construct()
